  await test('Desktop handle height and roving tabs','#target{color:red}',({i,w})=>{const root=i.shadowRoot;ok(root.querySelector('.rz.w').getBoundingClientRect().height>100,'west handle full height');i.show('css');ok(i.tabs.find(t=>t.id==='tab-html').tabIndex===-1,'inactive tab omitted');ok(i.tabs.find(t=>t.id==='tab-css').tabIndex===0,'selected tab focusable');ok(i.rows.get(i.ownerDocument.querySelector('#target')).pickButton.tagName==='BUTTON','native HTML selection button');});
