  await test('Disconnect cleans picking and reconnects','#target{color:red}',async({i,w,doc,t})=>{i.setPicking(true);i.remove();const e=new w.MouseEvent('click',{bubbles:true,cancelable:true});t.dispatchEvent(e);ok(!e.defaultPrevented,'page click released');ok(!i.connected,'disposed');doc.body.append(i);await tick(w);ok(i.connected,'reconnected');i.setPicking(true);const next=new w.MouseEvent('click',{bubbles:true,cancelable:true});t.dispatchEvent(next);ok(next.defaultPrevented,'picker works again');});
  await test('Batched paint requests','#target{color:red}',async({i,w})=>{await tick(w);let count=0;i.draw=()=>{count++};for(let k=0;k<20;k++)i.paint();await tick(w);ok(count===1,'one draw per frame');});
  await test('Exact inline attribute Reset','',({i,t})=>{const original=t.getAttribute('style');const d=i.store.allDecls.find(d=>d.prop==='margin-left');i.cssView.change(d,'20px');i.reset();ok(t.getAttribute('style')===original,'original attribute restored');},'<div id="target" style=" color: red ; margin-left: 2px; ">Target</div>');
  await test('Dynamic HTML refresh', '#target{color:red}',async({i,w,t})=>{t.textContent='Changed';t.className='new-class';await tick(w);ok(i.rows.get(t).pickButton.textContent.includes('Changed'),'text refreshed');ok(i.rows.get(t).pickButton.textContent.includes('new-class'),'class refreshed');});
  await test('RTL logical padding','#target{direction:rtl;padding-inline-start:30px;width:100px;height:50px}',({i,t,d})=>{i.cssView.hover=d('padding-inline-start');i.draw();const ring=i.painter.ov.querySelector('.pd');ok(ring.style.borderRightWidth==='30px','right-side band');ok(ring.style.borderLeftWidth==='0px','no left band');});
