  await test('Escape restores disabled declaration','#target{color:red;color:blue}',({i,w,t})=>{const d=i.store.allDecls.filter(d=>d.prop==='color')[1];d.on=false;i.apply(d);i.cssView.edit(d);const field=i.editor.field;field.value='green';field.dispatchEvent(new w.Event('input',{bubbles:true}));i.editor.finish(true);ok(!d.on,'still disabled');ok(w.getComputedStyle(t).color==='rgb(255, 0, 0)','fallback red restored');});
  await test('Vertical inline-size uses vertical measurement','#target{writing-mode:vertical-rl;inline-size:100px;block-size:50px}',({i,d})=>{i.cssView.hover=d('inline-size');i.draw();const line=i.painter.ov.querySelector('.dim-height');ok(!!line,'vertical line');ok(Math.abs(line.getBoundingClientRect().height-100)<1,'correct inline length');ok(!i.painter.ov.querySelector('.dim-width'),'not horizontal');});
