  await test('Style text replacement refreshes CSS','#target{color:red}',async({i,w,doc,d})=>{doc.styleSheets[0].ownerNode.textContent='#target{color:blue;padding:12px}';await tick(w);ok(d('color')?.value==='blue'&&!!d('padding'),'expected blue and padding; displayed '+i.store.allDecls.map(d=>`${d.prop}:${d.value}`).join(','));});
  await test('Inline attribute changes refresh CSS','#target{color:red}',async({i,w,t,d})=>{t.style.padding='12px';await tick(w);ok(!!d('padding'),'new inline padding should be visible');});
