  await test('Late external link refreshes after load','#target{color:red}',async({i,w,doc,d})=>{const link=doc.createElement('link');link.rel='stylesheet';link.href='/late.css';const loaded=new Promise(resolve=>{link.onload=resolve;link.onerror=()=>resolve();});doc.head.append(link);await loaded;await tick(w);if(i.loading)await i.loading;ok(doc.styleSheets.length===2,'late stylesheet actually loaded');ok(!!d('border-width'),'late linked border should be visible');});
