  await test('External live declarations survive edit and Reset','#target{color:red}',({i,w,doc,t,d})=>{const r=doc.styleSheets[0].cssRules[0];r.style.background='yellow';const before=r.style.cssText;i.cssView.change(d('color'),'blue');const afterEdit=r.style.cssText;i.reset();const afterReset=r.style.cssText;ok(backgroundSignature(r.style.background)===yellowBackground,`before=${before}; edit=${afterEdit}; Reset=${afterReset}; external yellow should survive`);});
